PKG = ROOT / "qseries_v2" / "oracle_intelligence"
PKG.mkdir(parents=True, exist_ok=True)

MODULE = PKG / "universal_market_adapter_replay_intelligence_engine.py"
TEST = ROOT / "test_oi_196_universal_market_adapter_replay_intelligence_engine.py"
INIT = PKG / "__init__.py"

MODULE_CODE = '"""\nOI-196 — Oracle Universal Market Adapter Replay Intelligence Engine\n\nRead-only intelligence layer for replay analytics artifacts.\n"""\nfrom __future__ import annotations\nfrom dataclasses import dataclass, field, asdict\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nfrom typing import Any, Dict, Iterable, List, Mapping, Optional\nimport json\n\nREAD_ONLY_GUARDRAILS = {\n    "oracle_read_only": True,\n    "executes_trades": False,\n    "routes_orders": False,\n    "submits_orders": False,\n    "manages_positions": False,\n    "execution_owner": "Q_SERIES_ONLY",\n}\n\ndef _utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\ndef _stable_json(value: Any) -> str:\n    return json.dumps(value, sort_keys=True, separators=(",", ":"), default=str)\n\ndef _hash(value: Any) -> str:\n    return sha256(_stable_json(value).encode("utf-8")).hexdigest()\n\ndef _safe_dict(value: Any) -> Dict[str, Any]:\n    if value is None:\n        return {}\n    if isinstance(value, Mapping):\n        return dict(value)\n    if hasattr(value, "to_dict"):\n        converted = value.to_dict()\n        if isinstance(converted, Mapping):\n            return dict(converted)\n    if hasattr(value, "__dict__"):\n        return dict(value.__dict__)\n    return {"value": value}\n\ndef _safe_list(value: Any) -> List[Any]:\n    if value is None:\n        return []\n    if isinstance(value, list):\n        return list(value)\n    if isinstance(value, tuple):\n        return list(value)\n    return [value]\n\ndef _lower(value: Any) -> str:\n    return str(value or "").strip().lower()\n\n@dataclass(frozen=True)\nclass ReplayIntelligenceFinding:\n    code: str\n    severity: str\n    message: str\n    evidence: Dict[str, Any] = field(default_factory=dict)\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n@dataclass(frozen=True)\nclass ReplayIntelligenceInsight:\n    insight_id: str\n    insight_type: str\n    title: str\n    summary: str\n    confidence: float\n    severity: str\n    evidence: Dict[str, Any] = field(default_factory=dict)\n    explainability: Dict[str, Any] = field(default_factory=dict)\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n@dataclass(frozen=True)\nclass ReplayIntelligenceReport:\n    report_id: str\n    created_at: str\n    oracle_instance_id: str\n    module_id: str\n    module_name: str\n    source_count: int\n    insight_count: int\n    finding_count: int\n    quality_score: float\n    report_hash: str\n    read_only_guardrails: Dict[str, Any]\n    insights: List[ReplayIntelligenceInsight]\n    findings: List[ReplayIntelligenceFinding]\n    telemetry: Dict[str, Any]\n    explainability: Dict[str, Any]\n    @property\n    def passed(self) -> bool:\n        return not any(item.severity in {"critical", "error"} for item in self.findings)\n    def to_dict(self) -> Dict[str, Any]:\n        data = asdict(self)\n        data["passed"] = self.passed\n        return data\n\nclass UniversalMarketAdapterReplayIntelligenceEngine:\n    module_id = "OI-196"\n    module_name = "Oracle Universal Market Adapter Replay Intelligence Engine"\n    def __init__(self, oracle_instance_id: str = "oracle.default") -> None:\n        self.oracle_instance_id = oracle_instance_id\n        self._reports: List[ReplayIntelligenceReport] = []\n\n    def generate_intelligence(self, replay_artifacts: Iterable[Any], *, intelligence_context: Optional[Mapping[str, Any]] = None) -> ReplayIntelligenceReport:\n        context = _safe_dict(intelligence_context)\n        artifacts = [self._normalize_artifact(item) for item in replay_artifacts]\n        findings = self._evaluate_inputs(artifacts, context)\n        insights = self._derive_insights(artifacts)\n        quality_score = self._quality_score(artifacts, insights, findings)\n        payload = {"oracle_instance_id": self.oracle_instance_id, "module_id": self.module_id, "context": context, "source_count": len(artifacts), "insights": [i.to_dict() for i in insights], "findings": [f.to_dict() for f in findings], "quality_score": quality_score}\n        report_hash = _hash(payload)\n        report = ReplayIntelligenceReport(\n            report_id="oi196.intelligence." + report_hash[:24],\n            created_at=_utc_now(),\n            oracle_instance_id=self.oracle_instance_id,\n            module_id=self.module_id,\n            module_name=self.module_name,\n            source_count=len(artifacts),\n            insight_count=len(insights),\n            finding_count=len(findings),\n            quality_score=quality_score,\n            report_hash=report_hash,\n            read_only_guardrails=dict(READ_ONLY_GUARDRAILS),\n            insights=insights,\n            findings=findings,\n            telemetry={\n                "module_id": self.module_id,\n                "module_name": self.module_name,\n                "oracle_instance_id": self.oracle_instance_id,\n                "source_count": len(artifacts),\n                "insight_count": len(insights),\n                "finding_count": len(findings),\n                "quality_score": quality_score,\n                "adapter_count": len({a.get("adapter_id") for a in artifacts if a.get("adapter_id")}),\n                "market_type_count": len({a.get("market_type") for a in artifacts if a.get("market_type")}),\n                "certified_count": sum(1 for a in artifacts if a.get("certified") is True),\n                "context_hash": _hash(context),\n            },\n            explainability={\n                "purpose": "Derive high-level replay intelligence from replay artifacts.",\n                "read_only_reason": "The engine only analyzes metadata and does not execute, route, submit, or manage positions.",\n                "execution_boundary": "Q Series remains the only execution engine.",\n                "canonical_contract": "Consumes replay artifacts with registration, certification, validation, manifest, adapter, market, telemetry, and explainability fields.",\n            },\n        )\n        self._reports.append(report)\n        return report\n\n    def generate_from_engines(self, *engines: Any, intelligence_context: Optional[Mapping[str, Any]] = None) -> ReplayIntelligenceReport:\n        artifacts: List[Any] = []\n        for engine in engines:\n            if hasattr(engine, "records"):\n                artifacts.extend(engine.records())\n            elif hasattr(engine, "results"):\n                artifacts.extend(engine.results())\n            elif hasattr(engine, "entries"):\n                artifacts.extend(engine.entries())\n            elif hasattr(engine, "reports"):\n                artifacts.extend(engine.reports())\n            else:\n                artifacts.append(engine)\n        return self.generate_intelligence(artifacts, intelligence_context=intelligence_context)\n\n    def reports(self) -> List[ReplayIntelligenceReport]:\n        return list(self._reports)\n    def latest_report(self) -> Optional[ReplayIntelligenceReport]:\n        return self._reports[-1] if self._reports else None\n    def telemetry_snapshot(self) -> Dict[str, Any]:\n        latest = self.latest_report()\n        return {"module_id": self.module_id, "module_name": self.module_name, "oracle_instance_id": self.oracle_instance_id, "report_count": len(self._reports), "latest_report_id": latest.report_id if latest else None, "latest_quality_score": latest.quality_score if latest else None, "latest_insight_count": latest.insight_count if latest else None, "read_only_guardrails": dict(READ_ONLY_GUARDRAILS)}\n    def intelligence_manifest(self) -> Dict[str, Any]:\n        return {"module_id": self.module_id, "oracle_instance_id": self.oracle_instance_id, "report_count": len(self._reports), "reports": [{"report_id": r.report_id, "report_hash": r.report_hash, "source_count": r.source_count, "insight_count": r.insight_count, "quality_score": r.quality_score, "passed": r.passed} for r in self._reports], "read_only_guardrails": dict(READ_ONLY_GUARDRAILS)}\n\n    def _normalize_artifact(self, artifact: Any) -> Dict[str, Any]:\n        data = _safe_dict(artifact)\n        telemetry = _safe_dict(data.get("telemetry"))\n        explainability = _safe_dict(data.get("explainability"))\n        certified = data.get("certified")\n        if certified is None:\n            certified = data.get("passed")\n        if certified is None:\n            certified = _lower(data.get("status")) in {"registered", "certified", "ok", "valid", "passed"}\n        return {\n            "artifact_id": str(data.get("registration_id") or data.get("certification_id") or data.get("validation_id") or data.get("manifest_id") or data.get("report_id") or data.get("id") or "artifact." + _hash(data)[:24]),\n            "registration_id": str(data.get("registration_id") or ""),\n            "certification_id": str(data.get("certification_id") or ""),\n            "validation_id": str(data.get("validation_id") or ""),\n            "manifest_id": str(data.get("manifest_id") or data.get("target_manifest_id") or ""),\n            "adapter_id": str(data.get("adapter_id") or telemetry.get("adapter_id") or data.get("source_adapter_id") or ""),\n            "market_type": str(data.get("market_type") or telemetry.get("market_type") or data.get("universal_market_type") or ""),\n            "symbol": str(data.get("symbol") or telemetry.get("symbol") or ""),\n            "status": str(data.get("status") or ""),\n            "certification_level": str(data.get("certification_level") or ""),\n            "certified": bool(certified),\n            "quality_score": float(data.get("quality_score") or telemetry.get("quality_score") or 0.0),\n            "warning_count": int(data.get("warning_count") or telemetry.get("warning_count") or 0),\n            "blocker_count": int(data.get("blocker_count") or telemetry.get("blocker_count") or 0),\n            "finding_count": int(data.get("finding_count") or telemetry.get("finding_count") or len(_safe_list(data.get("findings")))),\n            "telemetry": telemetry,\n            "explainability": explainability,\n            "raw_hash": _hash(data),\n        }\n\n    def _evaluate_inputs(self, artifacts: List[Dict[str, Any]], context: Dict[str, Any]) -> List[ReplayIntelligenceFinding]:\n        findings: List[ReplayIntelligenceFinding] = []\n        if not artifacts:\n            findings.append(ReplayIntelligenceFinding("NO_REPLAY_ARTIFACTS", "warning", "No replay artifacts were supplied for intelligence generation."))\n            return findings\n        scanned = _stable_json({"artifacts": artifacts, "context": context}).lower()\n        hard_terms = ["order_submitted", "trade_routed", "position_opened", "executed_trade"]\n        detected = [term for term in hard_terms if term in scanned]\n        if detected:\n            findings.append(ReplayIntelligenceFinding("EXECUTION_LANGUAGE_DETECTED", "warning", "Execution-like language appeared in replay metadata. Oracle remains read-only.", {"detected_terms": detected}))\n        missing_identity = [a["artifact_id"] for a in artifacts if not a.get("manifest_id") and not a.get("certification_id") and not a.get("registration_id")]\n        if missing_identity:\n            findings.append(ReplayIntelligenceFinding("WEAK_REPLAY_IDENTITY", "info", "Some replay artifacts have weak registry/certification/manifest identity metadata.", {"artifact_ids": missing_identity}))\n        blocker_artifacts = [a["artifact_id"] for a in artifacts if a.get("blocker_count", 0) > 0]\n        if blocker_artifacts:\n            findings.append(ReplayIntelligenceFinding("BLOCKED_REPLAY_ARTIFACTS_PRESENT", "warning", "Some replay artifacts contain blockers and should not be treated as high-quality evidence.", {"artifact_ids": blocker_artifacts}))\n        return findings\n\n    def _derive_insights(self, artifacts: List[Dict[str, Any]]) -> List[ReplayIntelligenceInsight]:\n        if not artifacts:\n            return []\n        insights: List[ReplayIntelligenceInsight] = []\n        total = len(artifacts)\n        certified_count = sum(1 for a in artifacts if a.get("certified") is True)\n        certification_rate = certified_count / total\n        insights.append(self._make_insight("certification_health", "Replay certification health", f"{certified_count} of {total} replay artifacts are certified.", round(0.70 + min(certification_rate, 1.0) * 0.25, 4), "info" if certification_rate >= 0.8 else "warning", {"certified_count": certified_count, "total": total, "certification_rate": round(certification_rate, 4)}, {"method": "certified artifact count divided by total artifacts"}))\n        adapter_counts = self._count_by(artifacts, "adapter_id")\n        top_adapter, top_count = max(adapter_counts.items(), key=lambda item: item[1])\n        concentration = top_count / total\n        insights.append(self._make_insight("adapter_concentration", "Replay adapter concentration", f"Adapter {top_adapter or \'unknown\'} appears in {top_count} of {total} replay artifacts.", round(0.75 + min(concentration, 1.0) * 0.20, 4), "warning" if concentration >= 0.75 and total > 1 else "info", {"adapter_counts": adapter_counts, "top_adapter": top_adapter, "concentration": round(concentration, 4)}, {"method": "count replay artifacts by adapter_id"}))\n        market_counts = self._count_by(artifacts, "market_type")\n        top_market_type, top_market_count = max(market_counts.items(), key=lambda item: item[1])\n        insights.append(self._make_insight("market_type_distribution", "Replay market type distribution", f"Market type {top_market_type or \'unknown\'} is the most common replay source.", 0.86, "info", {"market_type_counts": market_counts, "top_market_type": top_market_type, "top_count": top_market_count}, {"method": "count replay artifacts by market_type"}))\n        warnings = sum(a.get("warning_count", 0) for a in artifacts)\n        blockers = sum(a.get("blocker_count", 0) for a in artifacts)\n        if warnings or blockers:\n            insights.append(self._make_insight("replay_quality_risk", "Replay quality risk", f"Replay artifacts contain {warnings} warnings and {blockers} blockers.", 0.91, "warning" if blockers == 0 else "critical", {"warning_count": warnings, "blocker_count": blockers}, {"method": "aggregate warning_count and blocker_count"}))\n        completeness = self._metadata_completeness(artifacts)\n        insights.append(self._make_insight("metadata_completeness", "Replay metadata completeness", f"Replay metadata completeness score is {round(completeness * 100, 2)}%.", 0.88, "info" if completeness >= 0.7 else "warning", {"metadata_completeness": round(completeness, 4)}, {"method": "measure presence of key replay identity fields"}))\n        return insights\n\n    def _make_insight(self, insight_type: str, title: str, summary: str, confidence: float, severity: str, evidence: Dict[str, Any], explainability: Dict[str, Any]) -> ReplayIntelligenceInsight:\n        payload = {"oracle_instance_id": self.oracle_instance_id, "insight_type": insight_type, "title": title, "summary": summary, "confidence": confidence, "severity": severity, "evidence": evidence}\n        return ReplayIntelligenceInsight("oi196.insight." + _hash(payload)[:24], insight_type, title, summary, max(0.0, min(1.0, float(confidence))), severity, evidence, explainability)\n    def _count_by(self, artifacts: List[Dict[str, Any]], key: str) -> Dict[str, int]:\n        counts: Dict[str, int] = {}\n        for artifact in artifacts:\n            value = str(artifact.get(key) or "unknown")\n            counts[value] = counts.get(value, 0) + 1\n        return counts\n    def _metadata_completeness(self, artifacts: List[Dict[str, Any]]) -> float:\n        fields = ["artifact_id", "manifest_id", "certification_id", "adapter_id", "market_type"]\n        if not artifacts:\n            return 0.0\n        total_slots = len(artifacts) * len(fields)\n        filled = sum(1 for artifact in artifacts for field in fields if artifact.get(field))\n        return filled / total_slots if total_slots else 0.0\n    def _quality_score(self, artifacts: List[Dict[str, Any]], insights: List[ReplayIntelligenceInsight], findings: List[ReplayIntelligenceFinding]) -> float:\n        if not artifacts:\n            return 0.0\n        score = 100.0\n        score -= sum(1 for a in artifacts if not a.get("certified")) * 8.0\n        score -= sum(a.get("blocker_count", 0) for a in artifacts) * 12.0\n        score -= sum(a.get("warning_count", 0) for a in artifacts) * 2.0\n        score -= sum(1 for f in findings if f.severity in {"critical", "error"}) * 15.0\n        score += min(len(insights), 5) * 1.0\n        return round(max(0.0, min(100.0, score)), 4)\n\ndef create_replay_intelligence_engine(oracle_instance_id: str = "oracle.default") -> UniversalMarketAdapterReplayIntelligenceEngine:\n    return UniversalMarketAdapterReplayIntelligenceEngine(oracle_instance_id=oracle_instance_id)\n\n__all__ = ["READ_ONLY_GUARDRAILS", "ReplayIntelligenceFinding", "ReplayIntelligenceInsight", "ReplayIntelligenceReport", "UniversalMarketAdapterReplayIntelligenceEngine", "create_replay_intelligence_engine"]\n'
TEST_CODE = 'from qseries_v2.oracle_intelligence.universal_market_adapter_replay_intelligence_engine import (\n    READ_ONLY_GUARDRAILS,\n    UniversalMarketAdapterReplayIntelligenceEngine,\n    create_replay_intelligence_engine,\n)\n\ndef test_oi_196_universal_market_adapter_replay_intelligence_engine():\n    engine = create_replay_intelligence_engine("oracle.test")\n    artifacts = [\n        {"registration_id": "oi190.registration.001", "certification_id": "oi189.certification.001", "validation_id": "oi188.validation.001", "manifest_id": "oi187.manifest.001", "adapter_id": "adp.kalshi", "market_type": "prediction_market", "symbol": "KXTEST", "certified": True, "status": "registered", "warning_count": 1, "blocker_count": 0, "telemetry": {"quality_score": 97.5}, "explainability": {"purpose": "unit test artifact"}},\n        {"registration_id": "oi190.registration.002", "certification_id": "oi189.certification.002", "validation_id": "oi188.validation.002", "manifest_id": "oi187.manifest.002", "adapter_id": "adp.kalshi", "market_type": "prediction_market", "symbol": "KXTEST2", "certified": True, "status": "registered", "warning_count": 0, "blocker_count": 0},\n        {"registration_id": "oi190.registration.003", "certification_id": "oi189.certification.003", "validation_id": "oi188.validation.003", "manifest_id": "oi187.manifest.003", "adapter_id": "adp.polymarket", "market_type": "prediction_market", "symbol": "PMTEST", "certified": False, "status": "rejected", "warning_count": 0, "blocker_count": 1},\n    ]\n    report = engine.generate_intelligence(artifacts, intelligence_context={"gate": "unit", "scope": "replay_intelligence"})\n    assert report.module_id == "OI-196"\n    assert report.source_count == 3\n    assert report.insight_count >= 4\n    assert report.finding_count >= 1\n    assert report.quality_score < 100.0\n    assert len(report.report_hash) == 64\n    assert report.read_only_guardrails == READ_ONLY_GUARDRAILS\n    assert report.telemetry["certified_count"] == 2\n    assert report.telemetry["adapter_count"] == 2\n    assert report.passed is True\n    insight_types = {insight.insight_type for insight in report.insights}\n    assert "certification_health" in insight_types\n    assert "adapter_concentration" in insight_types\n    assert "market_type_distribution" in insight_types\n    assert "metadata_completeness" in insight_types\n    assert "replay_quality_risk" in insight_types\n    snapshot = engine.telemetry_snapshot()\n    assert snapshot["report_count"] == 1\n    assert snapshot["latest_report_id"] == report.report_id\n    assert snapshot["read_only_guardrails"] == READ_ONLY_GUARDRAILS\n    manifest = engine.intelligence_manifest()\n    assert manifest["module_id"] == "OI-196"\n    assert manifest["report_count"] == 1\n    assert manifest["reports"][0]["report_id"] == report.report_id\n    empty_report = engine.generate_intelligence([])\n    assert empty_report.source_count == 0\n    assert empty_report.quality_score == 0.0\n    assert any(f.code == "NO_REPLAY_ARTIFACTS" for f in empty_report.findings)\n    class DummyEngine:\n        def records(self):\n            return artifacts[:1]\n    from_engine = engine.generate_from_engines(DummyEngine())\n    assert from_engine.source_count == 1\n    assert from_engine.telemetry["certified_count"] == 1\n\nif __name__ == "__main__":\n    test_oi_196_universal_market_adapter_replay_intelligence_engine()\n    print("[PASS] OI-196 Universal Market Adapter Replay Intelligence Engine")\n'

MODULE.write_text(MODULE_CODE, encoding="utf-8")
TEST.write_text(TEST_CODE, encoding="utf-8")

